def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "grab_folder": And([
            self.robot_at(self.floor),
            self.object_at(self.folder, self.floor),
            self.chair_is_obstacle,
            self.space_is_cluttered
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
